// The page moves a pull request between the menu numbers from its live jobs, so
// it sorts CI states as the server's buildNavCounts does (#5123). The cases are
// generated by that function (internal/api/live_nav_counts_fixture_test.go):
// from each case's snapshot, the live jobs of every other case must end on the
// numbers the server gives that one.

import { describe, expect, test } from 'bun:test';
import table from '../../../tests/generated/live-nav-counts.json';
import type { NavCounts } from './nav-counts.svelte';
import { applyLiveCi } from './nav-counts-live';
import { foldPullRequest } from './pr-fold';

const KEY = 'github:acme/app#1';

describe('live menu numbers end where the server counts', () => {
  for (const to of table.cases) {
    const fold = foldPullRequest('github', to.jobs);
    // No jobs to fold: the row keeps the server's pill, so nothing moves.
    if (!fold) continue;

    test(`jobs that read: ${to.name}`, () => {
      for (const from of table.cases) {
        for (const before of from.variants) {
          const after = to.variants.find((v) => v.variant === before.variant);
          if (!after) throw new Error(`no ${before.variant} case`);
          const counts: NavCounts = {
            branches: { total: 0, failed: 0 },
            issues: { total: 0, failed: 0 },
            pullRequests: before.pullRequests,
            releases: before.releases,
            bots: before.bots,
          };

          const moved = applyLiveCi(
            counts,
            [before.pullRequest],
            new Map([[KEY, fold]]),
          );

          expect({
            case: `${from.name}, ${before.variant}`,
            pullRequests: moved?.pullRequests,
            releases: moved?.releases,
            bots: moved?.bots,
          }).toEqual({
            case: `${from.name}, ${before.variant}`,
            pullRequests: after.pullRequests,
            releases: after.releases,
            bots: after.bots,
          });
        }
      }
    });
  }
});
